 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page();page.goto('http://127.0.0.1:8000/');page.evaluate('''async()=>{const {academicSubjectReport,academicReportDocument}=await import('./cbse-academic-report.js');const people={a:{key:'a',name:'Synthetic Physics Learner',classId:'XII',section:'A',roll:'1',subjects:{physics:true},subjectCatalog:{physics:{name:'Physics'}}}};const mission={settings:{redBelow:33,greenFrom:75},exams:{one:{name:'Test 1',date:'2026-07-01'},two:{name:'Test 2',date:'2026-07-20'}},marks:{one:{studentKey:'a',subjectId:'physics',examId:'one',score:10,maximum:20},two:{studentKey:'a',subjectId:'physics',examId:'two',score:18,maximum:20}}};document.body.replaceChildren(academicReportDocument(document,academicSubjectReport(people,mission)));}''');assert page.locator('h1').inner_text()=='Class XII · Physics';assert 'Secure pass' in page.inner_text('body');assert 'Test 1' in page.inner_text('body');assert 'Test 2' in page.inner_text('body');assert '+40.0' in page.inner_text('body');assert page.locator('table').count()==2;page.pdf(path='/tmp/synthetic-xii-physics-history.pdf',format='A4',landscape=True);page.evaluate('''async()=>{const {academicBriefDocument}=await import('./cbse-academic-report.js');const s={person:{name:'Synthetic Support Learner',section:'A',roll:'2'},band:'critical',history:[],latest:{score:2,maximum:20,exam:{name:'Current test',date:'2026-11-01'}}};document.body.replaceChildren(academicBriefDocument(document,{classId:'XII',subjectName:'Physics',students:[s]}));}''');assert 'Remedial priority: 1 students' in page.inner_text('body');assert 'Urgent individual remedial support' in page.inner_text('body');assert 'Synthetic Support Learner' not in page.inner_text('body');assert page.locator('section').count()==0;assert page.locator('table').count()==2;assert 'Month-wise summary' in page.inner_text('body');page.pdf(path='/tmp/synthetic-physics-brief.pdf',format='A4',landscape=True);page.evaluate('''async()=>{const {renderAcademicReportControls}=await import('./cbse-academic-report-view.js');document.body.replaceChildren();renderAcademicReportControls(document.body,{a:{classId:'X',subjects:{hindi:true},subjectCatalog:{hindi:{name:'Hindi'}}},b:{classId:'XII',subjects:{physics:true,chem:true},subjectCatalog:{physics:{name:'Physics'},chem:{name:'Chemistry'}}}},{marks:{},exams:{}});}''');assert page.get_by_label('Report subject',exact=True).input_value()=='Physics';page.get_by_label('Report subject',exact=True).select_option('');assert page.get_by_label('Report subject',exact=True).input_value()=='';page.get_by_label('Report class',exact=True).select_option('X');assert page.get_by_label('Report subject',exact=True).locator('option').all_text_contents()==['All subjects','Hindi'];assert page.get_by_label('Report subject',exact=True).input_value()=='';assert page.get_by_role('button',name='Brief summary PDF',exact=True).is_enabled();page.evaluate('''async()=>{const {renderAcademicReportControls}=await import('./cbse-academic-report-view.js');document.body.replaceChildren();const person=(section,sectionId)=>({classId:'XII',section,sectionId,subjects:{physics:true},subjectCatalog:{physics:{name:'Physics'}}});renderAcademicReportControls(document.body,{a:person('A','a'),b:person('B','b')},{marks:{},exams:{},allocations:{a:{classId:'XII',sectionId:'a',subjectId:'physics',staffId:'one'},b:{classId:'XII',sectionId:'b',subjectId:'physics',staffId:'two'}}},{staff:{one:{name:'Teacher One',status:'active'},two:{name:'Teacher Two',status:'active'}}});}''');assert page.get_by_label('Report teacher',exact=True).locator('option').all_text_contents()==['All teachers','Teacher One','Teacher Two'];page.get_by_label('Report section',exact=True).select_option('b');assert page.get_by_label('Report teacher',exact=True).locator('option').all_text_contents()==['All teachers','Teacher Two'];b.close()
